import type { BankQuestion } from "@/lib/bank";

/** Syllogism (Reasoning): 103 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"reason-syllogism-1","question":"Statements: All cats are animals. All animals are living beings. Conclusions: I. All cats are living beings. II. Some living beings are cats.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Cats ⊂ animals ⊂ living beings, so I follows, and converting it gives II.","difficulty":"easy"},
  {"id":"reason-syllogism-2","question":"Statements: All pens are books. No book is a table. Conclusions: I. No pen is a table. II. Some books are pens.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Pens sit inside books, which never touch tables, so I follows; II is the conversion of “All pens are books”.","difficulty":"easy"},
  {"id":"reason-syllogism-3","question":"Statements: Some boys are players. All players are tall. Conclusions: I. Some boys are tall. II. All tall people are players.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The boys who are players are tall, so I follows. “All players are tall” cannot be reversed, so II does not.","difficulty":"easy"},
  {"id":"reason-syllogism-4","question":"Statements: Some apples are mangoes. Some mangoes are bananas. Conclusions: I. Some apples are bananas. II. Some bananas are mangoes.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"Two “some” statements give no link between apples and bananas. II just converts the second statement.","difficulty":"moderate"},
  {"id":"reason-syllogism-5","question":"Statements: No dog is a cat. All cats are pets. Conclusions: I. No dog is a pet. II. Some pets are not dogs.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"Dogs could still be pets, so I fails. The cats are pets that are not dogs, so II follows.","difficulty":"moderate"},
  {"id":"reason-syllogism-6","question":"Statements: All roses are flowers. Some flowers are red. Conclusions: I. Some roses are red. II. All red things are flowers.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":3,"explanation":"The red flowers may or may not include roses, and nothing says every red thing is a flower.","difficulty":"moderate"},
  {"id":"reason-syllogism-7","question":"Statements: Some teachers are doctors. No doctor is a lawyer. Conclusions: I. Some teachers are not lawyers. II. Some lawyers are teachers.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The teachers who are doctors cannot be lawyers, so I follows; II is only a possibility.","difficulty":"hard"},
  {"id":"reason-syllogism-8","question":"Statements: All A are B. Some B are C. No C is D. Conclusions: I. Some B are not D. II. Some A are C.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The B that are C cannot be D, so I follows. A may or may not overlap C.","difficulty":"hard"},
  {"id":"reason-syllogism-9","question":"Statements: Only a few phones are laptops. All laptops are tablets. Conclusions: I. Some phones are tablets. II. All phones being laptops is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The phones that are laptops are tablets, so I follows. “Only a few” rules out all phones being laptops.","difficulty":"hard"},
  {"id":"reason-syllogism-10","question":"Statements: All stars are planets. No planet is a moon. Some moons are satellites. Conclusions: I. Some satellites are not planets. II. No star is a moon.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"The satellites that are moons cannot be planets (I). Stars sit inside planets, which never touch moons (II).","difficulty":"very-hard"},
  {"id":"reason-syllogism-11","question":"Statements: Some X are Y. All Y are Z. No Z is W. Conclusions: I. Some X are not W. II. Some Z are X.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"The X that are Y are also Z and so cannot be W (I); those same X are Z, giving II.","difficulty":"very-hard"},
  {"id":"reason-syllogism-12","question":"Statements: All pencils are erasers. Some erasers are sharpeners. No sharpener is a scale. Conclusions: I. All pencils being sharpeners is a possibility. II. Some erasers are not scales.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Nothing stops pencils from all being sharpeners (I). The erasers that are sharpeners cannot be scales (II).","difficulty":"very-hard"},
  {"id":"reason-syllogism-13","question":"Statements: No man is a machine. Some machines are robots. All robots are smart. Conclusions: I. Some smart things are not men. II. Some machines are smart.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"The machines that are robots are smart (II), and being machines they are not men, so some smart things are not men (I).","difficulty":"very-hard"},
  {"id":"reason-syllogism-14","question":"Statements: All pens are books. Some books are tables. Conclusions: I. Some pens are tables. II. Some tables are books.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"The books that are tables need not be pens, so I does not follow. II is the converse of “some books are tables” and follows.","difficulty":"very-hard"},
  {"id":"reason-syllogism-15","question":"Statements: No cat is a dog. All dogs are rats. Conclusions: I. Some rats are not cats. II. No rat is a cat.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The rats that are dogs are not cats, so I follows. Other rats may be cats, so II does not.","difficulty":"very-hard"},
  {"id":"reason-syllogism-16","question":"Statements: Some A are B. No B is C. Conclusions: I. Some A are not C. II. Some C are A.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The A that are B cannot be C, so I follows. Nothing links C to A, so II does not.","difficulty":"very-hard"},
  {"id":"reason-syllogism-17","question":"Statements: Some pens are pencils. All pencils are boxes. No box is a cap. Conclusions: I. No pen is a cap. II. Some boxes are pens.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"The pens that are pencils are boxes, so II follows. Those pens are not caps, but the other pens may be, so I does not follow.","difficulty":"very-hard","source":"IBPS PO · SSC CGL"},
  {"id":"reason-syllogism-18","question":"Statements: All A are B. Some B are C. No C is D. Conclusions: I. Some A being D is a possibility. II. Some B are not D.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Nothing connects A with D, so A being D remains possible (I). The B that are C cannot be D, so II follows definitely.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk"},
  {"id":"reason-syllogism-19","question":"Statements: All birds have wings. All parrots are birds. Conclusions: I. All parrots have wings. II. Some winged creatures are parrots.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Parrots ⊂ birds ⊂ winged creatures, so I follows; the parrots inside the winged circle make II true as well.","difficulty":"easy","source":"SSC GD · RRB NTPC"},
  {"id":"reason-syllogism-20","question":"Statements: No fruit is a vegetable. All mangoes are fruits. Conclusions: I. No mango is a vegetable. II. Some vegetables are mangoes.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"Mangoes lie inside the fruit circle, which has no overlap with vegetables, so I follows and II is impossible.","difficulty":"easy","source":"SSC CHSL · SSC GD"},
  {"id":"reason-syllogism-21","question":"Statements: All chairs are tables. Some tables are wooden. Conclusions: I. Some chairs are wooden. II. Some wooden things are tables.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"The wooden part of the table circle need not touch the chair circle, so I does not follow. II is just the converse of 'some tables are wooden' and follows.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"reason-syllogism-22","question":"Statements: Some books are novels. All novels are stories. Conclusions: I. Some books are stories. II. All stories are novels.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The books that are novels lie inside stories, so I follows. Stories may extend beyond novels, so II does not follow.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"reason-syllogism-23","question":"Statements: No pen is a pencil. Some pencils are erasers. Conclusions: I. Some erasers are not pens. II. Some pens are erasers.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The erasers that are pencils cannot be pens (pen and pencil circles are disjoint), so I follows. Nothing links pens to erasers, so II is only a possibility.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"reason-syllogism-24","question":"Statements: Some cups are plates. All plates are spoons. Conclusions: I. Some spoons are cups. II. All cups are spoons.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"Cups that are plates are inside spoons, so some spoons are cups (I). Cups outside the plate circle may lie outside spoons, so II does not follow.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"reason-syllogism-25","question":"Statements: All A are B. No B is C. Conclusions: I. No A is C. II. Some C are not B.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"A sits inside B and B is disjoint from C, so no A is C (I). Since no C is B, every C lies outside B, so 'some C are not B' is certainly true (II).","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"reason-syllogism-26","question":"Statements: Some roads are streets. No street is a lane. Conclusions: I. Some roads are not lanes. II. No road is a lane.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The roads that are streets lie outside lanes, so I follows. Roads that are not streets could still be lanes, so II does not follow.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"reason-syllogism-27","question":"Statements: All X are Y. Some Y are Z. Conclusions: I. Some Z are X. II. Some Z being X is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"The Z-part of Y may or may not touch X, so I is not certain, but nothing rules it out, so II (a possibility) follows.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"reason-syllogism-28","question":"Statements: Only a few cars are buses. No bus is a truck. Conclusions: I. Some cars are not trucks. II. All cars being trucks is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"'Only a few cars are buses' means some cars are buses and some are not. The cars that are buses cannot be trucks, so I follows. Those same cars make 'all cars are trucks' impossible, so II does not follow.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-syllogism-29","question":"Statements: All keys are locks. No lock is a door. Some doors are windows. Conclusions: I. Some windows are not locks. II. Some keys being windows is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Windows that are doors lie outside locks, so I follows. Keys are inside locks, and windows that are not doors can overlap locks and keys, so II is possible and follows.","difficulty":"hard","source":"IBPS PO · SSC CGL"},
  {"id":"reason-syllogism-30","question":"Statements: All pens are caps. Some caps are inks. Conclusions: I. Some pens are inks. II. No pen is an ink.","options":["Only conclusion I follows","Only conclusion II follows","Either I or II follows","Neither I nor II follows"],"answer":2,"explanation":"The ink part of caps may or may not touch pens, so neither conclusion is certain. But I ('some are') and II ('none are') are complementary with the same subject and predicate, so exactly one must be true: either I or II follows.","difficulty":"hard","source":"IBPS PO · SBI Clerk"},
  {"id":"reason-syllogism-31","question":"Statements: No apple is a grape. All grapes are berries. Conclusions: I. Some berries are not apples. II. Some apples being berries is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Berries that are grapes are not apples, so I follows. Apples can overlap the non-grape part of berries, so II is possible and follows.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"reason-syllogism-32","question":"Statements: Some tables are chairs. All chairs are desks. No desk is a bench. Conclusions: I. Some tables are not benches. II. All benches being tables is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Tables that are chairs are desks, hence not benches: I follows. Benches are disjoint from desks only; they can all lie inside the non-desk part of tables, so II is possible.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-syllogism-33","question":"Statements: All flowers are leaves. All leaves are stems. No stem is a root. Conclusions: I. No flower is a root. II. Some roots are not leaves.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"Flowers ⊂ leaves ⊂ stems and stems are disjoint from roots, so no flower is a root (I). Every root lies outside stems and therefore outside leaves, so 'some roots are not leaves' is certain (II).","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"reason-syllogism-34","question":"Statements: Some cats are white. All white things are soft. Conclusions: I. Some cats are soft. II. Some soft things are not cats.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The white cats are soft, so I follows. Nothing says soft things extend beyond cats: the soft circle could be entirely cats, so II is not certain.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"reason-syllogism-35","question":"Statements: No A is B. Some B are C. All C are D. Conclusions: I. Some D are not A. II. Some A being C is a possibility.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":2,"explanation":"C that are B are D and cannot be A, so some D are not A (I). A is disjoint only from B; the part of C outside B can overlap A, so II is possible.","difficulty":"hard","source":"IBPS PO · SSC CGL"},
  {"id":"reason-syllogism-36","question":"Statements: Some M are N. All N are O. Some O are P. Conclusions: I. Some M are P. II. Some P are N.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":3,"explanation":"M reaches O only through N, and the P-part of O need not touch N or M at all. Neither conclusion is certain; both are mere possibilities, and they are not a complementary pair.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"reason-syllogism-37","question":"Statements: All books are pages. Some pages are words. No word is a letter. Conclusions: I. Some books are words. II. No book is a word.","options":["Only conclusion I follows","Only conclusion II follows","Either I or II follows","Neither I nor II follows"],"answer":2,"explanation":"Books sit inside pages; the word-part of pages may or may not include books, so neither I nor II is certain. Since 'some books are words' and 'no book is a word' are complementary (same subject and predicate, some/no), one of them must hold: either I or II follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-syllogism-38","question":"Statements: Only a few mangoes are ripe. All ripe things are sweet. No sweet thing is sour. Conclusions: I. Some mangoes are not sour. II. All mangoes being sweet is a possibility. III. Some sour things are mangoes.","options":["Only I and II follow","Only I follows","Only II and III follow","All three follow"],"answer":0,"explanation":"'Only a few mangoes are ripe' = some mangoes are ripe and some are not. Ripe mangoes are sweet, hence not sour: I follows. The unripe mangoes can still be sweet, so all mangoes being sweet is possible: II follows. III is only a possibility, not certain.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-syllogism-39","question":"Statements: All red things are blue. No blue thing is green. Some green things are yellow. Conclusions: I. Some yellow things are not red. II. No red thing is green. III. Some blue things are yellow.","options":["Only II follows","Only I and II follow","Only I and III follow","All three follow"],"answer":1,"explanation":"Red ⊂ blue and blue is disjoint from green, so no red is green (II). The yellow things that are green are outside blue, hence not red, so some yellow are not red (I). Nothing forces blue and yellow to overlap, so III does not follow.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"reason-syllogism-40","question":"Statements: Some pens are not pencils. All pencils are markers. Conclusions: I. Some pens are not markers. II. Some markers are pencils.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"Pens that are not pencils may still be markers (markers extend beyond pencils), so I does not follow. Pencils lie inside markers, so some markers are pencils (II).","difficulty":"very-hard","source":"IBPS PO · SBI Clerk"},
  {"id":"reason-syllogism-41","question":"Statements: No cup is a glass. Some glasses are bottles. All bottles are jars. Conclusions: I. All jars being cups is a possibility. II. Some jars are not cups.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"The bottles that are glasses are jars and cannot be cups, so some jars are definitely not cups (II). Those same jars make 'all jars are cups' impossible, so I does not follow.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-syllogism-42","question":"Statements: All trains are buses. Some buses are cars. No car is a bike. Conclusions: I. Some trains being bikes is a possibility. II. Some buses being bikes is a possibility. III. No train is a car.","options":["Only I and III follow","Only II follows","Only I and II follow","All three follow"],"answer":2,"explanation":"Bikes are disjoint only from cars. Trains (inside buses) and buses can both overlap bikes in the non-car region, so I and II are possible. Trains could lie inside the car-part of buses, so III is not certain.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-syllogism-43","question":"Statements: Some roses are red. All red things are bright. No bright thing is dull. Conclusions: I. Some roses are dull. II. No rose is dull.","options":["Only conclusion I follows","Only conclusion II follows","Either I or II follows","Neither I nor II follows"],"answer":2,"explanation":"Red roses are bright and hence not dull, so 'some roses are not dull' is certain, but that is not a listed conclusion. Roses that are not red could be dull or not, so neither I nor II is certain; as a complementary some/no pair, either I or II follows.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-syllogism-44","question":"Statements: All A are B. All B are C. Some C are D. Conclusions: I. Some D are A. II. No D is A. III. Some C are A.","options":["Only III follows","Only I and III follow","Only III and either I or II follow","Only II and III follow"],"answer":2,"explanation":"A ⊂ B ⊂ C, so some C are A (III). The D-part of C may or may not reach A, so neither I nor II is certain, but they are a complementary some/no pair, so one of them must hold: either I or II, together with III.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-syllogism-45","question":"Statements: No X is Y. No Y is Z. Conclusions: I. No X is Z. II. Some Z are not Y.","options":["Only conclusion I follows","Only conclusion II follows","Both I and II follow","Neither I nor II follows"],"answer":1,"explanation":"Two negative statements give no definite link between X and Z: X could overlap Z, so I does not follow. 'No Y is Z' means every Z is outside Y, so some Z are not Y is certain (II).","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"reason-syllogism-46","question":"Statements: Some A are B. Some B are C. Some C are D. Conclusions: I. Some A are D. II. Some A are not D. III. Some D being A is a possibility.","options":["Only III follows","Only III and either I or II follow","Neither follows","Only I and III follow"],"answer":1,"explanation":"A chain of 'some' statements gives no definite conclusion between A and D, so neither I nor II is certain; nothing prevents D overlapping A, so III follows. I ('some A are D') and II ('some A are not D') are complementary, so one of them must be true: III with either I or II.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-syllogism-47","question":"Statements: All lamps are bulbs. Only a few bulbs are tubes. No tube is a fan. Conclusions: I. Some bulbs are not fans. II. Some lamps are not tubes. III. All lamps being fans is a possibility.","options":["Only I and II follow","Only I follows","All three follow","Only I and III follow"],"answer":3,"explanation":"Bulbs that are tubes cannot be fans, so I follows. Lamps may lie entirely inside the tube-part of bulbs, so II is not certain. Lamps may lie entirely in the non-tube part of bulbs, which fans can cover, so III is possible.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"reason-syllogism-48","question":"Statements: All P are Q. No Q is R. All R are S. Conclusions: I. Some P are R. II. Some S are not Q. III. Some P are S.","options":["Only II follows","Only I and II follow","Only III follows","Only II and III follow"],"answer":0,"explanation":"P ⊂ Q and Q is disjoint from R, so I is definitely false. R lies inside S and outside Q, so some S (the R-part) are not Q: II follows. P could overlap the non-R part of S, but it need not, so III is only a possibility.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id": "reason-syllogism-49", "question": "Statements: All singers are dancers. Some dancers are actors. Conclusions: I. Some actors are dancers. II. All dancers are singers.", "options": ["Only conclusion II follows", "Only conclusion I follows", "Both I and II follow", "Neither I nor II follows"], "answer": 1, "explanation": "I is the converse of 'Some dancers are actors', so it follows. Singers sit inside dancers, but dancers can be bigger than singers, so II does not follow.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "reason-syllogism-50", "question": "Statements: All books are papers. All papers are trees. Conclusions: I. Some trees are books. II. All trees are papers.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 0, "explanation": "Venn: books ⊂ papers ⊂ trees. Books are trees, so some trees are books (I follows). Trees may be larger than papers, so II does not follow.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "reason-syllogism-51", "question": "Statements: Some doctors are engineers. All engineers are writers. Conclusions: I. Some writers are doctors. II. Some doctors are not writers.", "options": ["Only conclusion II follows", "Either I or II follows", "Both I and II follow", "Only conclusion I follows"], "answer": 3, "explanation": "The doctors who are engineers lie inside writers, so some writers are doctors (I). All doctors could also be writers, so II is not certain.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "reason-syllogism-52", "question": "Statements: All lions are animals. No animal is a plant. Conclusions: I. No lion is a plant. II. Some animals are lions.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 2, "explanation": "Lions ⊂ animals and animals are disjoint from plants, so no lion is a plant (I). Since all lions are animals, some animals are lions (II).", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "reason-syllogism-53", "question": "Statements: Some phones are cameras. Some cameras are laptops. Conclusions: I. Some phones are laptops. II. No phone is a laptop.", "options": ["Neither I nor II follows", "Either I or II follows", "Only conclusion I follows", "Both I and II follow"], "answer": 1, "explanation": "Two 'some' statements give no definite link between phones and laptops, so neither is certain alone. But I ('some are') and II ('no') are a complementary pair about the same terms, so one of them must be true: either I or II.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "reason-syllogism-54", "question": "Statements: All gold is metal. Some metals are costly. Conclusions: I. Some gold is costly. II. Some costly things are metals.", "options": ["Only conclusion II follows", "Only conclusion I follows", "Both I and II follow", "Neither I nor II follows"], "answer": 0, "explanation": "Gold sits inside metal, but the costly part of metal may lie outside gold, so I is not certain. II is the converse of 'Some metals are costly', so it follows.", "difficulty": "moderate", "source": "RRB NTPC · SSC CHSL"},
  {"id": "reason-syllogism-55", "question": "Statement: Only a few teachers are poets. Conclusions: I. Some teachers are not poets. II. Some poets are teachers.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Neither I nor II follows", "Both I and II follow"], "answer": 3, "explanation": "'Only a few A are B' means some A are B and some A are not B. So some teachers are not poets (I) and, by conversion, some poets are teachers (II).", "difficulty": "moderate", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-56", "question": "Statements: Some pens are blue. No blue thing is red. All red things are bright. Conclusions: I. Some pens are not red. II. Some bright things are not blue.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 2, "explanation": "The pens that are blue cannot be red, so I follows. Red lies inside bright and is fully outside blue, so the red part of bright is not blue: II follows.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "reason-syllogism-57", "question": "Statements: All A are B. No C is B. Some D are C. Conclusions: I. Some D are not A. II. Some A are D.", "options": ["Only conclusion II follows", "Only conclusion I follows", "Both I and II follow", "Either I or II follows"], "answer": 1, "explanation": "The D that are C lie outside B, and A is inside B, so those D are not A: I follows. A and D need not meet, so II does not follow.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "reason-syllogism-58", "question": "Statements: Only a few cups are glasses. All glasses are mugs. Conclusions: I. All cups being mugs is a possibility. II. Some mugs are cups.", "options": ["Both I and II follow", "Only conclusion I follows", "Only conclusion II follows", "Neither I nor II follows"], "answer": 0, "explanation": "The cups that are glasses lie inside mugs, so some mugs are cups (II). The cups that are not glasses are free to fall inside mugs too, so 'all cups are mugs' is possible (I). Both follow.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-59", "question": "Statements: No tree is a shrub. All shrubs are plants. Some plants are herbs. Conclusions: I. Some herbs being trees is a possibility. II. All shrubs being herbs is a possibility.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Neither I nor II follows", "Both I and II follow"], "answer": 3, "explanation": "Trees are barred only from shrubs, so a tree can be a herb (I possible). Shrubs sit inside plants and nothing stops all of them lying in the herb part (II possible). Both follow.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-60", "question": "Statements: Some keys are locks. All locks are doors. No door is a window. Conclusions: I. No key is a window. II. Some windows being keys is a possibility.", "options": ["Only conclusion I follows", "Either I or II follows", "Only conclusion II follows", "Both I and II follow"], "answer": 2, "explanation": "Keys that are locks are doors and so not windows, but keys outside locks are free to be windows. So I is not certain and II is a valid possibility.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "reason-syllogism-61", "question": "Statements: All apples are fruits. Some fruits are sweet. No sweet thing is bitter. Conclusions: I. Some apples are sweet. II. No apple is bitter.", "options": ["Only conclusion I follows", "Neither I nor II follows", "Only conclusion II follows", "Both I and II follow"], "answer": 1, "explanation": "Apples sit inside fruits but may lie wholly outside the sweet part, so I is not certain. Apples outside 'sweet' can be bitter, so II is not certain either. Neither follows.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "reason-syllogism-62", "question": "Statements: No P is Q. All Q are R. All R are S. Conclusions: I. Some S are not P. II. No P is R.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Either I or II follows"], "answer": 0, "explanation": "Q ⊂ R ⊂ S and Q is outside P, so the Q part of S is not P: I follows. P is barred only from Q, so P can overlap the rest of R; II does not follow.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "reason-syllogism-63", "question": "Statements: Some ideas are plans. No plan is a dream. All dreams are goals. Conclusions: I. Some goals are not plans. II. Some ideas are not dreams. III. All ideas being goals is a possibility.", "options": ["Only I and II follow", "Only II and III follow", "Only I follows", "All I, II and III follow"], "answer": 3, "explanation": "Dreams ⊂ goals and dreams are outside plans, so some goals (the dreams) are not plans: I. The ideas that are plans cannot be dreams: II. Plans are barred only from dreams, so ideas (including idea-plans) can all lie in the non-dream part of goals: III possible. All follow.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-64", "question": "Statements: All circles are squares. Only a few squares are triangles. No triangle is a line. Conclusions: I. Some squares are not lines. II. All circles being triangles is a possibility. III. Some circles are lines.", "options": ["Only I follows", "Only II and III follow", "Only I and II follow", "All I, II and III follow"], "answer": 2, "explanation": "The squares that are triangles cannot be lines: I. Circles can all fall in the triangle part of squares, as long as some squares stay outside triangles: II possible. Circles need not touch lines, so III is not certain.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-65", "question": "Statements: No man is perfect. Some perfect beings are gods. Conclusions: I. Some gods are not men. II. No god is a man. III. Some men being gods is a possibility.", "options": ["Only I and II follow", "Only I and III follow", "Only II follows", "Only III follows"], "answer": 1, "explanation": "The gods who are perfect cannot be men: I. Gods outside 'perfect' are free to be men, so II is not certain while III is a valid possibility.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "reason-syllogism-66", "question": "Statements: All roads are paths. All paths are lanes. Some lanes are streets. No street is a highway. Conclusions: I. Some lanes are not highways. II. Some roads being streets is a possibility. III. All paths being highways is a possibility.", "options": ["All I, II and III follow", "Only I and II follow", "Only I and III follow", "Only I follows"], "answer": 0, "explanation": "The lanes that are streets are not highways: I. Roads ⊂ paths ⊂ lanes, and roads may overlap the street part: II possible. Paths may sit wholly in the non-street part of lanes and all be highways: III possible.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-67", "question": "Statements: Some A are B. All B are C. Some C are D. No D is E. Conclusions: I. Some A are C. II. Some C are not E. III. Some A are not E.", "options": ["Only I follows", "All I, II and III follow", "Only II and III follow", "Only I and II follow"], "answer": 3, "explanation": "A–B lies inside C: I. The C that are D are outside E: II. But A (even A–B) may lie in the non-D part of C and be wholly E, so III is not certain.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-68", "question": "Statements: All teachers are learners. No learner is lazy. Some lazy people are rich. Conclusions: I. Some rich people are not teachers. II. No teacher is lazy. III. Some learners are rich.", "options": ["Only II follows", "All I, II and III follow", "Only I and II follow", "Only I and III follow"], "answer": 2, "explanation": "Teachers ⊂ learners and learners are outside lazy, so no teacher is lazy: II. The rich who are lazy are outside learners, hence not teachers: I. Learners may or may not be rich, so III is only a possibility.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "reason-syllogism-69", "question": "Statements: Some birds are crows. All crows are black. Conclusions: I. Some birds are not black. II. All birds are black.", "options": ["Neither I nor II follows", "Either I or II follows", "Only conclusion II follows", "Both I and II follow"], "answer": 1, "explanation": "The crow-birds are black, but the other birds are undecided, so neither I nor II is definite. I ('some birds are not black') and II ('all birds are black') are exact opposites, so one must be true: either I or II.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-70", "question": "Statements: Only a few books are novels. No novel is a comic. All comics are magazines. Conclusions: I. Some books are not comics. II. All books being magazines is a possibility. III. Some magazines are not novels.", "options": ["All I, II and III follow", "Only I and III follow", "Only I and II follow", "Only III follows"], "answer": 0, "explanation": "The books that are novels are not comics: I. Novels are barred only from comics, so books (including novel-books) can all be magazines outside the comic part: II possible. Comics ⊂ magazines and comics are not novels: III.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-71", "question": "Statements: No pen is a pencil. No pencil is an eraser. Conclusions: I. Some pens are erasers. II. No pen is an eraser.", "options": ["Only conclusion II follows", "Neither I nor II follows", "Both I and II follow", "Either I or II follows"], "answer": 3, "explanation": "Two negative statements give no link between pens and erasers, so neither conclusion is certain on its own. But I ('some are') and II ('no') form a complementary pair, so either I or II follows.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "reason-syllogism-72", "question": "Which pair of statements definitely leads to the conclusion 'Some cats are dogs'?", "options": ["All cats are animals; some animals are dogs", "All dogs are pets; some pets are cats", "Some cats are pets; all pets are dogs", "No cat is a bird; some birds are dogs"], "answer": 2, "explanation": "Some cats are pets and all pets lie inside dogs, so those cats are dogs. In the other pairs the middle term (animals, pets, birds) may connect to cats and dogs in different parts, so no definite link.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-73", "question": "Statements: All X are Y. Some Y are not Z. Conclusions: I. Some X are not Z. II. All X being Z is a possibility. III. Some Y are not X.", "options": ["Only I follows", "Only II follows", "Only II and III follow", "Only I and III follow"], "answer": 1, "explanation": "The Y that are not Z may lie outside X, so I is not certain and 'all X are Z' stays possible: II. X may be the whole of Y, so III is not certain either.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "reason-syllogism-74", "question": "Statement: Only doctors are surgeons. Conclusions: I. All surgeons are doctors. II. All doctors are surgeons.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 0, "explanation": "'Only doctors are surgeons' means every surgeon is a doctor, so I follows. It does not say every doctor is a surgeon, so II does not.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "reason-syllogism-75", "question": "Statement: Not all birds can fly. Conclusions: I. No bird can fly. II. Some birds cannot fly.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 1, "explanation": "'Not all birds can fly' means at least some birds cannot fly, so II follows. It does not rule out that some birds fly, so I does not.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "reason-syllogism-76", "question": "Statement: All engineers are graduates. Conclusions: I. Some graduates are engineers. II. Some engineers are graduates.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 2, "explanation": "From 'All engineers are graduates', 'Some engineers are graduates' follows directly, and its converse 'Some graduates are engineers' follows too.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "reason-syllogism-77", "question": "Statements: None but the brave deserve the fair. Rahul deserves the fair. Conclusions: I. All brave people deserve the fair. II. Rahul is brave.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 1, "explanation": "'None but the brave deserve the fair' means everyone who deserves the fair is brave. Rahul deserves the fair, so he is brave (II). It does not say every brave person deserves the fair (I).", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "reason-syllogism-78", "question": "Statements: Some pens are not costly. All useful things are costly. Conclusions: I. Some pens are not useful. II. Some costly things are useful.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 2, "explanation": "Useful things lie wholly inside costly things, so the pens that are not costly cannot be useful: I follows. 'All useful things are costly' converts to 'Some costly things are useful': II follows.", "difficulty": "moderate", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-79", "question": "Statements: Some actors are singers. No singer is a dancer. Which conclusion definitely follows?", "options": ["No actor is a dancer", "Some dancers are actors", "Some singers are dancers", "Some actors are not dancers"], "answer": 3, "explanation": "The actors who are singers cannot be dancers, so 'Some actors are not dancers' is certain. The other actors may or may not dance, so the first two are only possible, and the third contradicts the second statement.", "difficulty": "moderate", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-80", "question": "Statements: Some cars are red. Some cars are not red. Conclusions: I. All cars being red is a possibility. II. Some red things are cars.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 1, "explanation": "'Some red things are cars' is the converse of 'Some cars are red', so II follows. I is ruled out by the second statement, since some cars are definitely not red.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "reason-syllogism-81", "question": "Statements: At least some politicians are honest. All honest people are respected. Conclusions: I. Some politicians are respected. II. All politicians being honest is a possibility.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 2, "explanation": "The honest politicians are respected, so I follows. Nothing stops every politician from being honest, so II is a valid possibility.", "difficulty": "moderate", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-82", "question": "Statements: No fish is a bird. No bird is a reptile. Conclusions: I. Some fish being reptiles is a possibility. II. No reptile is a fish.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 0, "explanation": "Two negative statements give no definite link between fish and reptiles, so II does not follow. For the same reason a fish–reptile overlap cannot be ruled out, so I (a possibility) follows.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "reason-syllogism-83", "question": "Statements: All A are B. Some B are not C. All C are D. Conclusions: I. Some D are not A. II. Some B are D. III. All A being C is a possibility.", "options": ["Only I follows", "Only II follows", "Only III follows", "Only II and III follow"], "answer": 2, "explanation": "All of D could lie inside A (with C inside D and A inside B), so I fails. B and D need not meet at all, so II fails. A can sit inside C while some other B stays outside C, so III is possible.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-84", "question": "Statements: Only gold is yellow. Some ornaments are yellow. Conclusions: I. All gold is yellow. II. Some ornaments are gold.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 1, "explanation": "'Only gold is yellow' means every yellow thing is gold. The yellow ornaments are therefore gold, so II follows. It does not say all gold is yellow, so I does not.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-85", "question": "Statements: All P are Q. Some R are not Q. Conclusions: I. Some R are not P. II. Some P are not R.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 0, "explanation": "P lies inside Q, so the R that lie outside Q are also outside P: I follows. All P may well be R, so II does not.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "reason-syllogism-86", "question": "Statements: Many teachers are researchers. No researcher is idle. Conclusions: I. Some teachers are not idle. II. All idle people being teachers is a possibility.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 2, "explanation": "'Many' is read as 'some'. The teachers who are researchers are not idle, so I follows. The idle people can all be teachers who are not researchers, so II is possible.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-87", "question": "Statements: All circles are triangles. All triangles are squares. Conclusions: I. All squares are circles. II. All circles are squares. III. Some squares are triangles. IV. All squares being circles is a possibility.", "options": ["Only II and III follow", "Only II, III and IV follow", "All four follow", "Only II follows"], "answer": 1, "explanation": "Circles ⊂ triangles ⊂ squares, so II and III follow. I is not certain, but if the three sets are equal it holds, so IV (a possibility) follows.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-88", "question": "Statements: Some A are not B. Some B are not C. Conclusions: I. Some A are not C. II. Some C are not A.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "answer": 3, "explanation": "Two particular negative statements give no valid conclusion. A could lie wholly inside C, and C wholly inside A, so neither I nor II is certain.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "reason-syllogism-89", "question": "Which pair of statements definitely leads to the conclusion 'Some flowers are not red'?", "options": ["All flowers are plants; some plants are not red", "Some red things are flowers; some flowers are roses", "No red thing is a lily; some lilies are not flowers", "Some flowers are roses; no rose is red"], "answer": 3, "explanation": "The flowers that are roses cannot be red, so 'Some flowers are not red' is certain. In the other pairs every flower could still be red.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-90", "question": "Statements: All A are B. All C are B. No B is D. Conclusions: I. No A is D. II. Some A are C. III. No C is D.", "options": ["Only I follows", "Only I and III follow", "Only III follows", "All three follow"], "answer": 1, "explanation": "A and C both lie inside B, and B shares nothing with D, so neither A nor C can be D: I and III follow. A and C may not overlap, so II does not.", "difficulty": "hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "reason-syllogism-91", "question": "Statements: Only a few doctors are surgeons. Only a few surgeons are professors. Conclusions: I. Some doctors are not surgeons. II. Some surgeons are professors. III. Some doctors are professors.", "options": ["Only I and II follow", "Only I and III follow", "Only II and III follow", "All three follow"], "answer": 0, "explanation": "'Only a few X are Y' means some X are Y and some X are not Y. So I and II follow directly. The professor-surgeons need not be doctors, so III is not certain.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-92", "question": "Statements: All P are Q. Some Q are R. No R is S. All S are T. Conclusions: I. Some T are not R. II. Some P being S is a possibility. III. Some Q are not S.", "options": ["Only I and II follow", "Only I and III follow", "Only II and III follow", "All I, II and III follow"], "answer": 3, "explanation": "I: S lies inside T and outside R, so those T are not R. III: the Q that are R cannot be S. II: nothing forbids a P that is also S, so the possibility holds. All three follow.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-93", "question": "Statements: Some coins are not gold. All gold is precious. No precious thing is cheap. Conclusions: I. Some coins are not cheap. II. All coins being precious is a possibility. III. Some precious things are not cheap.", "options": ["Only I follows", "Only II and III follow", "Only I and III follow", "All three follow"], "answer": 1, "explanation": "III: gold exists, is precious and is not cheap. II: the non-gold coins could still be precious. I fails: the coins could all be non-gold and cheap without breaking any statement.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-94", "question": "Statements: All A are B. Some B are C. Conclusions: I. Some A are not C. II. All A are C.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Either I or II follows", "Neither I nor II follows"], "answer": 2, "explanation": "Neither follows by itself, since A may or may not lie inside C. But I and II are exact opposites (a 'some … not' and an 'all' on the same terms), so one of them must be true: Either I or II follows.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-95", "question": "Statements: Some boys are tall. Some tall people are smart. Conclusions: I. Some boys are smart. II. Some boys are not smart.", "options": ["Only conclusion I follows", "Only conclusion II follows", "Either I or II follows", "Neither I nor II follows"], "answer": 3, "explanation": "Neither follows. 'Either' would need the two to be a complementary pair, but here both could be true together (some boys smart, others not), so they are not opposites. Answer: neither.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-96", "question": "Statements: All hills are mountains. No mountain is a valley. Some valleys are rivers. All rivers are streams. Conclusions: I. Some streams are not hills. II. No hill is a river. III. Some streams are valleys.", "options": ["Only I and II follow", "Only I and III follow", "Only II and III follow", "All three follow"], "answer": 1, "explanation": "The valley-rivers are streams (III), and being valleys they are not mountains, hence not hills (I). Rivers that are not valleys may be hills, so II is not certain.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "reason-syllogism-97", "question": "Statement: All teachers are punctual. Which additional statement, together with it, makes the conclusion 'No teacher is lazy' definitely true?", "options": ["All lazy people are punctual", "Some punctual people are not lazy", "No punctual person is lazy", "Some lazy people are not teachers"], "answer": 2, "explanation": "If no punctual person is lazy, then teachers, who all lie inside 'punctual', cannot be lazy. The other options leave room for a lazy teacher.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-98", "question": "Statements: Some doors are windows. All windows are walls. No wall is a roof. Some roofs are floors. Conclusions: I. Some floors are not walls. II. Some doors are not roofs. III. Some floors being doors is a possibility. IV. All windows being floors is a possibility.", "options": ["Only I and II follow", "Only I, II and III follow", "All four follow", "Only II and IV follow"], "answer": 2, "explanation": "I: roof-floors are not walls. II: door-windows are walls, hence not roofs. III: a door outside the windows can be a floor. IV: floors may cover all of the windows (inside the walls, away from the roofs). All four follow.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-99", "question": "Statements: No A is B. Some B are C. Some C are D. Conclusions: I. Some C are not A. II. Some D are not A. III. All D being B is a possibility.", "options": ["Only I and III follow", "Only I follows", "Only I and II follow", "Only II and III follow"], "answer": 0, "explanation": "I: the C that are B cannot be A. II fails: D could lie wholly inside A (meeting C outside B). III: D can lie wholly inside B, overlapping C there. So I and III.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-100", "question": "Statement: All that glitters is not gold. Conclusions: I. Some glittering things are not gold. II. No glittering thing is gold. III. Some glittering things being gold is a possibility.", "options": ["Only I follows", "Only II follows", "Only II and III follow", "Only I and III follow"], "answer": 3, "explanation": "The proverb means 'not everything that glitters is gold', i.e. some glittering things are not gold (I). It does not say none is gold, so II fails and the possibility in III stays open.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "reason-syllogism-101", "question": "Statements: Some X are Y. No Y is Z. All Z are X. Conclusions: I. Some X are not Z. II. Some X are not Y. III. Some Y are Z.", "options": ["Only I follows", "Only I and II follow", "Only II and III follow", "All three follow"], "answer": 1, "explanation": "I: the X that are Y cannot be Z. II: Z lies inside X and outside Y, so those X are not Y. III directly contradicts 'No Y is Z'.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-102", "question": "Statements: All mangoes are fruits. Only fruits are sweet. Conclusions: I. All sweet things are fruits. II. Some sweet things are mangoes. III. All mangoes being sweet is a possibility.", "options": ["Only I and III follow", "Only I and II follow", "Only II follows", "All three follow"], "answer": 0, "explanation": "'Only fruits are sweet' means all sweet things are fruits (I). Mangoes and sweet things both sit inside fruits but need not meet, so II fails, while III remains possible.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "reason-syllogism-103", "question": "Statements: No P is Q. All Q are R. Some R are S. No S is T. Conclusions: I. Some R are not P. II. Some R are not T. III. All P being S is a possibility.", "options": ["Only I and II follow", "Only II and III follow", "All three follow", "Only I follows"], "answer": 2, "explanation": "I: the R that are Q are not P. II: the R that are S are not T. III: P only has to avoid Q, so it can lie wholly inside S. All three follow.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
];

export default questions;
